          model = { ...model, isDashboardDetailed: !model.isDashboardDetailed }
          publish(engine)
          void engine.storeSet(detailsStoreKeyOf('workflows'), model.isDashboardDetailed).catch(error => engine.log(messageOf(error)))
        },
      },
