  /** Open findings of a workflow's review ledger: the sweep-level sibling YAML, else the markdown. */
  async function openFindingsCount(engine: Host, root: string, workflow: WorkflowEntry): Promise<number | null> {
    const dir = joinPath(root, '.ai', 'workflows', workflow.slug)
    let names: string[]
    try {
      names = (await engine.reader.list(dir)).filter(entry => entry.kind === 'file').map(entry => entry.name)
    } catch {
      return null
    }
    const chosen = reviewLedgerNameOf(names, workflow.selectedSlice)
    if (chosen === null) return null
    try {
      return openFindingsOf(await engine.reader.read(joinPath(dir, chosen)))
    } catch {
      return null
    }
  }

  on('ui.open', { id: DASHBOARD_PANE }, async ($, e, next) => {
    // F2: the open state comes from the pane's own events and lives in `$.state`, so a reload keeps the body.
    const result = await next(e)
    model = { ...model, isDashboardOpen: true }
    if (host !== null) publish(host)
    return result
  })

  on('ui.close', { id: DASHBOARD_PANE }, async ($, e, next) => {
    model = { ...model, isDashboardOpen: false }
    if (host !== null) publish(host)
    return next(e)
  })

  on('tool.call', { tool: WRITE_TOOL_PATTERN }, async ($, e, next) => {
    const engine = host
    const input = e as unknown as Record<string, unknown>
    const path = typeof input['file_path'] === 'string' ? input['file_path'] : typeof input['notebook_path'] === 'string' ? input['notebook_path'] : null
    const agent = agentKeyOf(e.agentId)
    const mode = settings.readCheck
    const target = engine && path !== null && mode !== 'off' ? await readCheckTarget(engine, path, agent) : null
    if (engine && target !== null && mode === 'block') {
      // A deny after the write would leave the file written and tell the agent
      // it failed: the block runs before the write (Y3).
      const outcome = await runReadCheck(engine, target)
      const waiver = isClean(outcome) ? null : waiverOf(writtenTextOf(input))
      await appendLedgerRow(engine, target, outcome, waiver)
      if (!isClean(outcome) && waiver === null) return { deny: contextTextOf({ artifact: target.file, reference: target.match.entry.reference, result: outcome, mode: 'block' }) }
    }
    const result = await next(e)
    if (engine) await afterWrite(engine, path, result.deny === undefined && result.isError !== true)
    if (!engine || target === null || result.deny !== undefined || result.isError === true) return result
    if (target.agent === MAIN_AGENT) mainReadSinceCheck = false
    if (mode !== 'warn') return result
    const outcome = await runReadCheck(engine, target)
    await appendLedgerRow(engine, target, outcome, null)
    if (isClean(outcome)) return result
    const text = contextTextOf({ artifact: target.file, reference: target.match.entry.reference, result: outcome, mode: 'warn' })
    return { ...result, context: [...(result.context ?? []), text] }
  })

  /** The write bookkeeping: the turn's writes, the active workflow, the strip. */
  async function afterWrite(engine: Host, path: string | null, isWritten: boolean): Promise<void> {
    if (model.root === null || !isWritten) return
    if (path === null || !isWorkflowPath(model.root, path)) return
    // A background sub-agent writes between the turns of a parked stage.
    const stage = bracket ?? parked
    if (stage !== null) stage.writes.push(path)
    const slug = slugOfPath(model.root, path)
    if (slug !== null && stage?.command?.slug == null) {
      model = { ...model, active: slug }
      await remember(engine)
    }
    await refreshActive(engine)
  }

  /**
   * The stage artifact a write lands, when the read check runs on it: a file
   * under a workflow, not an excluded file, that a `writes` row of a stage
   * the writer runs names (the roster write-back by implement or verify is
   * not checked).
   */
  async function readCheckTarget(engine: Host, path: string, agent: string): Promise<CheckTarget | null> {
    if (model.root === null) return null
    const where = classifyPath(path, model.root)
    if (where === null || where.kind !== 'artifact' || isExcludedWrite(where.file)) return null
    const requires = requiresNow()
    if (matchWrite(requires, where.file) === null) return null
    // The stages the writer is running: every stage whose reference the writer
    // read (a yolo stage agent reads its own), then the main loop's `/wf`
    // command. Only their `writes` rows match: a file several stages write
    // (`05-implement.md`, `03-slice.md`, `04-plan.md`) written by a stage that
    // does not list it (implement, verify, the driver) is not checked.
    const stages = writerStagesOf(requires, reads.get(agent), agent === MAIN_AGENT ? (bracket?.command ?? null) : null, agent === MAIN_AGENT ? (bracket?.readMark ?? 0) : 0)
    if (stages.length === 0) return null
    const roster = (await readSlices(engine, where.slug)).map(slice => slice.slug.toLowerCase())
    // A review dimension file (`07-review-auth-security.md`) is no slice `auth-security`.
    const acceptSlice = (slice: string) => roster.includes(slice) || !roster.some(known => slice.startsWith(`${known}-`))
    const match = matchWrite(requires, where.file, stages, acceptSlice, stages)
    if (match === null) return null
    return { agent, slug: where.slug, file: where.file, id: where.id, match }
  }

  /** The check for one target: the writer's reads against the stage's rows. Never throws. */
  async function runReadCheck(engine: Host, target: CheckTarget): Promise<CheckResult> {
    if (model.root === null) return { missing: [], partial: [] }
    const io: Io = {
      exists: path => engine.reader.exists(path),
      read: path => readIfPresent(engine, path),
      list: async dir => (await engine.reader.list(dir)).filter(entry => entry.kind === 'file').map(entry => entry.name),
    }
    try {
      const required = requiredOf(target.match, target.slug)
      return await checkReads(required, { root: model.root, slug: target.slug, reads: reads.get(target.agent), fed: fedByOutput.get(target.id) ?? [], self: target.id }, io)
    } catch (error) {
      engine.log(`wf read check: ${messageOf(error)}`)
      return { missing: [], partial: [] }
    }
  }

  /** One `.read-ledger.jsonl` row per check, through the append queue; a failure is one log line. */
  async function appendLedgerRow(engine: Host, target: CheckTarget, outcome: CheckResult, waiver: string | null): Promise<void> {
    if (model.root === null) return
    const path = joinPath(model.root, '.ai', 'workflows', target.slug, READ_LEDGER_FILE)
    let at: string
    try {
      at = new Date(await engine.now()).toISOString()
    } catch {
      at = new Date(0).toISOString()
    }
    const line = ledgerLineOf({ at, agentId: target.agent, stage: target.match.entry.stage, artifact: target.file, missing: outcome.missing, partial: outcome.partial, waiver })
    appendQueue = appendQueue
      .then(() => engine.appendFile(path, line))
      .catch(error => engine.log(`wf read check: the ledger row was not written: ${messageOf(error)}`))
    await appendQueue
  }

  on('tool.call', { tool: 'Read' }, async ($, e, next) => {
    const result = await next(e)
    if (result.deny !== undefined || result.isError === true) return result
    const where = classifyPath(e.file_path, model.root)
    if (where === null) return result
    // The probe journal: one row per loop per session proves the hook fires, and whether it carries an agentId (W0).
    journal?.readFired(e.agentId, e.file_path)
    const agent = agentKeyOf(e.agentId)
    recordRead(reads, agent, where.id, e.file_path, readFactOf(result.result))
    if (agent === MAIN_AGENT) mainReadSinceCheck = true
    return result
  })

  on('tool.call', { tool: AGENT_TOOL_PATTERN }, async ($, e, next) => {
    // Recorded before the call: a foreground agent writes its artifact before
    // the Agent call returns.
    const input = e as unknown as Record<string, unknown>
    const prompt = input['prompt']
    if (typeof prompt === 'string' && requiresNow().length > 0) {
      const fed = promptFedOf(prompt)
      if (fed !== null && fed.inputs.length > 0) {
        for (const output of fed.outputs) {
          if (matchWrite(requiresNow(), output.file) === null) continue
          const id = artifactIdOf(output.slug, output.file)
          fedByOutput.delete(id)
          fedByOutput.set(id, fed.inputs)
        }
        while (fedByOutput.size > FED_CAP) {
          const oldest = fedByOutput.keys().next().value
          if (oldest === undefined) break
          fedByOutput.delete(oldest)
        }
      }
    }
    return next(e)
  })

  on('tool.call', { tool: /^AskUserQuestion$/u }, async ($, e, next) => {
    if (bracket !== null) bracket.questions += 1
    return next(e)
  })

  // A background sub-agent outlives the main turn that started it: the main
  // model answers "waiting" and its turn ends before the stage writes its
  // artifact. The `/wf` turn records the sub-agent so its end is not the
  // stage's end.
  on('agent.spawn', async ($, e, next) => {
    const result = await next(e)
    if (e.background && e.parentAgentId === undefined && result.agentId !== undefined && bracket?.command != null) bracket.background.add(result.agentId)
    return result
  })

  on('turn.start', async ($, e, next) => {
    const engine = host
    const result = await next(e)
    if (!engine) return result
    const startedAt = await engine.now()
    // The text of a slash-command turn may be the expanded skill; the
    // dispatcher's own run, seconds before, names the command then.
    const typed = wfCommandOf(e.text)
    const command = typed ?? (lastRun !== null && startedAt - lastRun.at < LAST_RUN_WINDOW_MS ? lastRun.command : null)
    lastRun = null
    // A turn that names no `/wf` command continues a parked stage: it is the
    // notification of a background sub-agent, or the person waiting with it.
    const resumed = command === null ? parked : null
    parked = null
    bracket = resumed ?? { turnId: e.turnId, startedAt, command, costAtStart: await engine.costUsd(), writes: [], questions: 0, background: new Set(), readMark: readMarkOf() }
    if (command?.slug) setActive(engine, command.slug)
    if (command !== null) await live.started(command.key, command.slug).catch(error => engine.log(messageOf(error)))
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    const engine = host
    // A sub-agent raises no `turn.start` but does raise `turn.complete` with
    // its `agentId`. It is not the person's turn: it must not consume the
    // bracket, or the first sub-agent to finish ends the stage's bookkeeping
    // and the writes that follow it are counted against nothing.
    if (e.agentId !== undefined) {
      // A sub-agent's reads end with it.
      reads.delete(e.agentId)
      bracket?.background.delete(e.agentId)
      parked?.background.delete(e.agentId)
      return result
    }
    const turn = bracket
    bracket = null
    if (!engine || turn === null) return result
    const command = turn.command
    // The main model answered while its background sub-agents still run: the
    // stage is not over. Park it; the check and the compaction wait for the
    // turn that ends with no sub-agent of the stage running.
    if (command !== null && e.reason === 'answer' && turn.background.size > 0) {
      parked = turn
      if (turn.writes.length > 0) await refreshActive(engine)
      journalTurn(command, turn, null, `wait(${turn.background.size})`)
      return result
    }
    if (command !== null && !READ_ONLY_KEYS.has(command.key)) {
      const costNow = await engine.costUsd()
      if (costNow !== null && turn.costAtStart !== null) model = { ...model, lastStageUsd: Math.max(0, costNow - turn.costAtStart) }
    }
    if (turn.writes.length > 0 || command !== null) await refreshActive(engine)
    else return result
    const workflow = activeWorkflow()
    // Whether the stage landed: a `/wf <key> <slug> [slice]` turn the person
    // did not interrupt must have written the key's artifact. The check's
    // toast and the compaction read the same answer.
    let landed: boolean | null = null
    if (command !== null && command.slug !== null && e.reason === 'answer' && model.root !== null) {
      const expected = expectedArtifactOf(command)
      // A name with `*` has no single file to stat: only the turn's writes can show it.
      const at = expected === null || expected.includes('*') ? null : await engine.mtime(joinPath(model.root, '.ai', 'workflows', command.slug, expected))
      landed = stageLanded(turn.writes, expected, turn.startedAt, at)
      if (settings.stageCheck && expected !== null && !landed) {
        const text = `wf: ${command.key} ended without ${expected}`
        engine.toast(text)
        engine.log(text)
      }
    }
    // The next step, dim in the prompt box, Tab to take.
    const suggestion = settings.suggestNext && workflow !== null && !workflow.terminal && workflow.nextInvocation && turn.writes.length > 0 ? workflow.nextInvocation : null
    const suggest = () => {
      if (suggestion === null) return
      engine.suggest(suggestion).catch(error => {
        journal?.callFailed('suggest', messageOf(error))
        engine.log(messageOf(error))
      })
    }
    // The post-stage compaction, between turns; the suggestion follows it so
    // the dim text is proposed on the compacted session.
    if (settings.stageCompact && landed === true && command !== null && workflow !== null && compactEligible(command, workflow, e)) {
      const instructions = compactInstructionsOf(workflow, command, turn.writes)
      const key = command.key
      journalTurn(command, turn, landed, 'compact')
      // Inside this dispatch, not in a timer it starts: the engine accepts
      // `session.compact` from a `turn.complete` hook and refuses it from a
      // later event, which is what a detached call becomes.
      await compactAfterStage(engine, key, instructions)
      engine.later(suggest)
      return result
    }
    if (command !== null) journalTurn(command, turn, landed, compactSkipReason(command, workflow, landed, e, suggestion))
    // Proposed once this dispatch is over: the engine drops a suggestion made while a turn runs.
    if (suggestion !== null) engine.later(suggest)
    return result
  })

  /**
   * One journal row per `/wf` turn: what ran, what it wrote, whether its
   * artifact landed, and what followed. A turn that compacted nothing says
   * which test refused it, so one row answers "why did it not compact".
   */
  function journalTurn(command: WfCommand, turn: Bracket, landed: boolean | null, action: string): void {
    const target = `${command.key} ${command.slug ?? '-'}${command.slice === null ? '' : ` ${command.slice}`}`
    void journal?.write({
      event: 'turn',
      ok: action === 'compact' || action === 'suggest',
      detail: `${target} · writes ${turn.writes.length} · landed ${landed === null ? 'n/a' : String(landed)} · ${action}`,
    })
  }

  /** Why a `/wf` turn compacted nothing, in one word the journal carries. */
  function compactSkipReason(command: WfCommand, workflow: WorkflowEntry | null, landed: boolean | null, end: { reason: string; agentId?: string | undefined }, suggestion: string | null): string {
    if (!settings.stageCompact) return 'off'
    if (landed !== true) return 'unlanded'
    if (!compactEligible(command, workflow, end)) return `ineligible(${command.key})`
    return suggestion === null ? 'none' : 'suggest'
  }

  /**
   * One compaction after a landed stage: the toast, the call, one retry when
   * the engine refused the first as inside a turn, and a log line for a veto
   * or a second refusal. Never throws.
   */
  async function compactAfterStage(engine: Host, key: string, instructions: string): Promise<void> {
    engine.toast(compactToastOf(key, await engine.contextPercent()))
    // One attempt, here. The engine accepts `session.compact` from a
    // `turn.complete` hook and refuses it from any later event, so a retry on
    // a timer would ask from the one place that cannot be answered.
    await compactOnce(engine, instructions, 'turn.complete')
  }

  /** One compaction call, journalled with the engine's own words for a refusal. */
  async function compactOnce(engine: Host, instructions: string, label: string): Promise<'done' | 'skipped' | 'refused'> {
    try {
      const outcome = await engine.compact(instructions)
      if (outcome.skip === undefined) {
        void journal?.write({ event: 'compact', ok: true, detail: `${label} done` })
        return 'done'
      }
      engine.log(`wf: compaction skipped: ${outcome.skip}`)
      void journal?.write({ event: 'compact', ok: false, detail: `${label} skipped: ${outcome.skip}` })
      return 'skipped'
    } catch (error) {
      const message = messageOf(error)
      engine.log(`wf: compaction refused: ${message}`)
      void journal?.write({ event: 'compact', ok: false, detail: `${label} refused: ${message}` })
      return 'refused'
    }
  }

  on('session.compact', async ($, e, next) => {
    // Every compaction of the main conversation, while a workflow is active,
    // keeps the workflow's position: one sentence ahead of the instructions.
    // A precompute installs nothing and passes through.
    // The main loop's read ledger resets between stages, so the next stage
    // reads its inputs again; a compaction in the middle of a stage (a stage
    // turn open, reads since its last checked write) keeps it.
    if (e.agentId === undefined && e.trigger !== 'precompute' && !(bracket !== null && mainReadSinceCheck)) {
      reads.delete(MAIN_AGENT)
      mainReadSinceCheck = false
    }
    const workflow = activeWorkflow()
    if (!settings.stageCompact || e.agentId !== undefined || e.trigger === 'precompute' || workflow === null) return next(e)
    const sentence = compactKeepSentenceOf(workflow)
    if (e.instructions?.includes(sentence)) return next(e)
    const instructions = e.instructions === undefined || e.instructions === '' ? sentence : `${sentence} ${e.instructions}`
    return next({ ...e, instructions })
  })

  on('prompt.suggest', { origin: { kind: 'suggestion' } }, async ($, e, next) => {
    // The engine's own guess yields to the workflow's next step while one is active.
    const workflow = activeWorkflow()
    if (!settings.suggestNext || workflow === null || workflow.terminal || !workflow.nextInvocation) return next(e)
    return next({ ...e, text: workflow.nextInvocation })
  })

  on('ui.press', { plugin: PLUGIN_NAME }, async ($, e, next) => {
    // A row press reads the workflow tree before it shows the next step or
    // fills the prompt; the press resolves once that work is done.
    const result = await next(e)
    await pending
    return result
  })

  on('ui.scroll', { component: 'AbovePrompt' }, ($, e, next) => {
    // The band never has rows to scroll (a scrolling band arms no digit), so
    // the wheel over it, and the page keys while it holds the keyboard, turn
    // the page instead; the engine's window stays where it is.
    const engine = host
    if (!engine || model.step === null || e.by === 0) return next(e)
    turnPage(engine, e.by < 0 ? -1 : 1)
    return {}
  })

  on('ui.focus', { component: 'AbovePrompt' }, async ($, e, next) => {
    // Tab past the last row lands on the next page's first row; Shift+Tab
    // before the first row lands on the previous page's last row. Any other
    // move is the engine's, remembered so the next one can be judged.
    const engine = host
    const step = model.step
    if (!engine || step === null || e.origin.kind !== 'person') return next(e)
    const { options } = await rowsOf(engine, step)
    const size = pageSizeOf(ringMaxRows)
    const page = pageOf(options, model.page, size)
    const rowKeys = page.items.map(item => rowKeyOf(item.value))
    const first = rowKeys[0]
    const last = rowKeys[rowKeys.length - 1]
    const landsOnRow = e.element !== undefined && rowKeys.includes(e.element)
    let by = 0
    if (page.pages > 1 && !landsOnRow && model.ring === last) by = 1
    else if (page.pages > 1 && !landsOnRow && model.ring === first) by = -1
    if (by === 0 || first === undefined) {
      model = { ...model, ring: e.element ?? null }
      return next(e)
    }
    const target = pageOf(options, model.page + by, size)
    const landing = by > 0 ? target.items[0] : target.items[target.items.length - 1]
    if (landing === undefined) return next(e)
    const key = rowKeyOf(landing.value)
    model = { ...model, page: model.page + by, ring: key }
    publish(engine)
    // Land the ring on the new page's row through the chain; when the new
    // tree is not drawn yet, ask again once this dispatch is over.
    const moved = await next({ ...e, element: key })
    if (moved.deny !== undefined) {
      engine.later(() => {
        void engine.focus(e.requestId, key).then(again => {
          if (again.deny !== undefined) engine.log(`sdlc-workflow: the ring did not follow the page: ${again.deny}`)
        })
      })
    }
    return {}
  })

  on('prompt.edit', async ($, e, next) => {
    // The picker follows the draft: `/wf` opens the key step over the strip,
    // each word typed narrows the rows, and a finished word moves to the next step.
    const result = await next(e)
    const engine = host
    if (!engine) return result
    notePrompt(`edit raised · ${model.surface ?? 'none'}`)
    if (!drawsHere()) return result
    try {
      const drafted = draftStepOf(result.text)
      if (drafted === null) {
        if (isDraftDriven && model.step !== null) close(engine)
        return result
      }
      // A picker a command opened keeps its own field; the box does not move it.
      if (model.step !== null && !isDraftDriven) return result
      notePrompt(`edit drives the picker · ${model.surface ?? 'none'}`)
      const step = drafted.step
      if (step.kind !== 'key') await readWorkflows(engine, false)
      if (step.kind === 'slice' && !model.slices.has(step.slug)) await readSlices(engine, step.slug)
      if (step.kind === 'slice' && (model.slices.get(step.slug) ?? []).length === 0) {
        if (isDraftDriven) close(engine)
        return result
      }
      const isSame = isSameStep(model.step, step)
      if (isSame && model.filter === drafted.filter) return result
      isDraftDriven = true
      model = { ...model, step, filter: drafted.filter, page: isSame && model.filter === drafted.filter ? model.page : 0, ring: null }
      publish(engine)
    } catch (error) {
      journal?.callFailed('edit', messageOf(error))
    }
    return result
  })

  on('prompt.submit', ($, e, next) => {
    // Any submission ends the pick: the person typed past it. A compaction
    // never happens here: the engine refuses `session.compact` from this hook,
    // because the hook holds the turn it would compact under.
    if (host && model.step !== null) close(host)
    return next(e)
  })
}

/** A Read result's line facts; a result without them (an image, a notebook) counts as the whole file. */
function readFactOf(result: unknown): ReadFact {
  const file = result && typeof result === 'object' ? (result as { file?: unknown }).file : undefined
  if (file && typeof file === 'object') {
    const { startLine, numLines, totalLines } = file as { startLine?: unknown; numLines?: unknown; totalLines?: unknown }
    if (typeof startLine === 'number' && typeof numLines === 'number' && typeof totalLines === 'number') return { startLine, numLines, totalLines }
  }
  return { startLine: 1, numLines: 0, totalLines: 0 }
}

/** A `/wf` command line with its spacing made one: what `issued` compares. */
function commandKeyOf(text: string): string {
  return text.trim().split(/\s+/u).join(' ')
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

export { PLUGIN_NAME }

files.hooks/mod/active.ts:
/**
 * The active workflow and the turn bracket: pure helpers the strip, the
 * next-step suggestion, the stage-landed check, the post-stage compaction,
 * the driver status, and the dashboard read. Nothing here touches the engine.
 */
import { entryOf } from './catalog.ts'
import { readCheckModeOf } from './readledger.ts'
import type { ReadCheckMode } from './readledger.ts'
import type { SliceEntry, WorkflowEntry } from './workflows.ts'

/** The settings the manifest's `userConfig` declares, defaults filled in. */
export type Settings = {
  strip: boolean
  suggestNext: boolean
  stageCheck: boolean
  questionProgress: boolean
  driverStatus: boolean
  spinnerVerb: boolean
  cost: boolean
  hubNotice: boolean
  stageCompact: boolean
  probeJournal: boolean
  /** The usage guard (WF-CAMPAIGN-PLAN.md 17). */
  usageGuard: boolean
  /** The read check (ARTIFACT-SPLIT-PLAN.md S6): `warn`, `block`, or `off`. */
  readCheck: ReadCheckMode
}

/** The settings that are switches: every one but `readCheck`. */
export type SwitchName = Exclude<keyof Settings, 'readCheck'>

export const SETTING_NAMES: ReadonlyArray<SwitchName> = [
  'strip',
  'suggestNext',
  'stageCheck',
  'questionProgress',
  'driverStatus',
  'spinnerVerb',
  'cost',
  'hubNotice',
  'stageCompact',
  'probeJournal',
  'usageGuard',
]

/** Every setting on, as the manifest defaults them. */
export const DEFAULT_SETTINGS: Settings = {
  strip: true,
  suggestNext: true,
  stageCheck: true,
  questionProgress: true,
  driverStatus: true,
  spinnerVerb: true,
  cost: true,
  hubNotice: true,
  stageCompact: true,
  probeJournal: true,
  usageGuard: true,
  readCheck: 'warn',
}

/** The settings from the plugin's options: a boolean field takes its value, anything else its default. */
export function settingsOf(options: Readonly<Record<string, unknown>>): Settings {
  const settings: Settings = { ...DEFAULT_SETTINGS }
  for (const name of SETTING_NAMES) {
    const value = options[name]
    if (typeof value === 'boolean') settings[name] = value
  }
  settings.readCheck = readCheckModeOf(options['readCheck'])
  return settings
}

/** The setting a `config.set` key names (`sdlc-workflow.strip`), or null. */
export function settingOfKey(pluginName: string, key: string): SwitchName | null {
  const prefix = `${pluginName}.`
  if (!key.startsWith(prefix)) return null
  const name = key.slice(prefix.length)
  return (SETTING_NAMES as readonly string[]).includes(name) ? (name as SwitchName) : null
}

/** The `/wf` command a turn ran, parsed from the prompt text. */
export type WfCommand = { key: string; slug: string | null; slice: string | null }

/**
 * The `/wf <key> [slug] [slice]` a prompt starts with, or null. A
 * `/wf-<key> ...` command and the namespaced `/sdlc-workflow:wf` form parse
 * the same way. An unknown key is null: the dispatcher refuses it.
 */
export function wfCommandOf(text: string): WfCommand | null {
  const match = /^\s*\/(?:sdlc-workflow:)?wf(?:-([a-z-]+))?(?:\s+(.*))?$/su.exec(text)
  if (match === null) return null
  const rest = (match[2] ?? '').trim()
  const tokens = rest === '' ? [] : rest.split(/\s+/u)
  let key = match[1] ?? null
  if (key === null) {
    key = tokens.shift() ?? null
  }
  if (key === null || entryOf(key) === null) return null
  const slug = tokens[0] ?? null
  const slice = tokens[1] ?? null
  return { key, slug: slug === undefined ? null : slug, slice: slice === undefined ? null : slice }
}

/**
 * The stage file a key writes for a slug and a slice, or null when the key
 * writes none the check can name. A `*` stands for any text: ship writes one
 * `09-ship-run-<run-id>.md` per release (the legacy `09-ship.md` is read-only),
 * and `/wf implement <slug> reviews` writes `05-implement-<slice>.md` for the
 * slices it fixes.
 */
export function expectedArtifactOf(command: WfCommand): string | null {
  const { key, slice } = command
  if (key === 'implement' && slice === 'reviews') return '05-implement-*.md'
  const withSlice = (stem: string) => (slice === null || slice === 'all' ? null : `${stem}-${slice}.md`)
  switch (key) {
    case 'shape':
      return '02-shape.md'
    case 'slice':
      return '03-slice.md'
    case 'plan':
      return withSlice('04-plan')
    case 'implement':
      return withSlice('05-implement')
    case 'verify':
      return withSlice('06-verify')
    case 'handoff':
      return '08-handoff.md'
    case 'ship':
      return '09-ship-run-*.md'
    case 'retro':
      return '10-retro.md'
    default:
      return null
  }
}

/**
 * Whether a stage turn landed its artifact: the expected file is in the turn's
 * writes, or its modification time is at or after the turn's start. Without an
 * expected file (`plan <slug> all`, a key with no artifact) any write under the
 * workflow counts.
 */
export function stageLanded(writes: readonly string[], expected: string | null, startedAt: number, mtime: number | null): boolean {
  if (expected === null) return writes.length > 0
  const name = expected.toLowerCase()
  const pattern = new RegExp(`^${name.split('*').map(part => part.replace(/[.+?^${}()|[\]\\]/gu, '\\$&')).join('.*')}$`, 'u')
  if (writes.some(path => pattern.test(basenameOf(path)))) return true
  return mtime !== null && mtime >= startedAt
}

/** The keys whose landed turn is a stage boundary the mod compacts at; `review` is exempt (its findings feed the fix turn). */
export const COMPACT_KEYS: ReadonlySet<string> = new Set(['shape', 'slice', 'plan', 'implement', 'verify', 'handoff', 'ship', 'retro'])

/** The end of a turn as `turn.complete` reports it, the fields the compaction decision reads. */
export type TurnEnd = { reason: string; agentId?: string | undefined }

/**
 * Whether a landed stage turn is one the mod compacts after: the model answered
 * (no interruption, refusal, or error), on the main loop, a `/wf <key> <slug>`
 * of a compacting key, with a workflow still open and a next step to take.
 */
export function compactEligible(command: WfCommand | null, workflow: WorkflowEntry | null, end: TurnEnd): boolean {
  if (command === null || workflow === null) return false
  if (end.reason !== 'answer' || end.agentId !== undefined) return false
  if (command.slug === null || !COMPACT_KEYS.has(command.key)) return false
  if (workflow.terminal || !workflow.nextInvocation) return false
  return true
}

/** Past this many paths the instructions name the count, not the list. */
const COMPACT_PATH_LIMIT = 12

/** The instructions the post-stage compaction hands the summarizer: what to keep, never a format. */
export function compactInstructionsOf(workflow: WorkflowEntry, command: WfCommand, writes: readonly string[]): string {
  const parts = [`The /wf ${command.key} stage of workflow ${workflow.slug} is complete.`]
  const keep = [`the workflow slug ${workflow.slug}`]
  if (workflow.selectedSlice) keep.push(`the selected slice ${workflow.selectedSlice}`)
  keep.push(`the next invocation ${workflow.nextInvocation ?? ''}`.trimEnd())
  parts.push(`Keep ${keep.join(', ')}.`)
  const paths = [...new Set(writes)]
  if (paths.length > COMPACT_PATH_LIMIT) parts.push(`Keep the paths of the ${paths.length} artifacts written this turn under .ai/workflows/${workflow.slug}/.`)
  else if (paths.length > 0) parts.push(`Keep the paths of the artifacts written this turn: ${paths.join(', ')}.`)
  parts.push('Keep verbatim every decision, acceptance criterion, blocker, and answer the person gave that is not yet written to an artifact.')
  parts.push('Drop tool output, test logs, and file contents; the next stage re-reads the artifacts from disk.')
  return parts.join(' ')
}

/** The sentence every compaction gains while a workflow is active: its position and its files. */
export function compactKeepSentenceOf(workflow: WorkflowEntry): string {
  const items = [`the active /wf workflow ${workflow.slug}`]
  if (workflow.currentStage) items.push(`its stage ${workflow.currentStage}`)
  if (workflow.selectedSlice) items.push(`its slice ${workflow.selectedSlice}`)
  if (workflow.nextInvocation) items.push(`its next invocation ${workflow.nextInvocation}`)
  items.push(`the paths under .ai/workflows/${workflow.slug}/`)
  return `Keep ${items.join(', ')}.`
}

/** The toast before a post-stage compaction; the percent is left out when the usage read gave none. */
export function compactToastOf(key: string, percent: number | null): string {
  return percent === null ? `wf: compacting after ${key}` : `wf: compacting after ${key} (context ${percent}%)`
}

/** True when `path` lies under `<root>/.ai/workflows`, on either slash. */
export function isWorkflowPath(root: string, path: string): boolean {
  const base = `${normalizePath(root)}/.ai/workflows/`
  return normalizePath(path).startsWith(base)
}

/** The workflow slug a path under `.ai/workflows` belongs to, or null. */
export function slugOfPath(root: string, path: string): string | null {
  const base = `${normalizePath(root)}/.ai/workflows/`
  const normal = normalizePath(path)
  if (!normal.startsWith(base)) return null
  const rest = normal.slice(base.length)
  const slug = rest.split('/')[0] ?? ''
  return slug === '' || rest.indexOf('/') === -1 ? null : slug
}

/** The file name at the end of a path. */
export function basenameOf(path: string): string {
  const normal = normalizePath(path)
  return normal.slice(normal.lastIndexOf('/') + 1)
}

export function normalizePath(path: string): string {
  return path.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()
}

/** The strip's first row for a workflow: slug, stage, slice with its roster count, and the next step. */
export function stripTextOf(workflow: WorkflowEntry, slices: readonly SliceEntry[]): string {
  const parts = [`wf ${workflow.slug}`]
  if (workflow.terminal) {
    parts.push(`closed (${workflow.status})`)
    return parts.join(' · ')
  }
  if (workflow.status !== 'active') parts.push(workflow.status)
  if (workflow.currentStage) parts.push(workflow.currentStage)
  if (workflow.selectedSlice) {
    const complete = slices.filter(slice => slice.status === 'complete' || slice.status === 'completed').length
    const count = slices.length > 0 ? ` (${complete} of ${slices.length} complete)` : ''
    parts.push(`slice ${workflow.selectedSlice}${count}`)
  }
  if (workflow.nextInvocation) parts.push(`next: ${workflow.nextInvocation}`)
  return parts.join(' · ')
}

/**
 * The pinned status line, the one row that stays when the band is hidden:
 * the next invocation (the strip's identity and roster are not repeated),
 * the last stage's dollars, and the hub in short.
 */
export function statusTextOf(workflow: WorkflowEntry, stageUsd: number | null = null, hub: HubHealth | null = null): string {
  const parts: string[] = []
  if (workflow.terminal) parts.push(`wf ${workflow.slug} · closed`)
  else if (workflow.nextInvocation) parts.push(`next ${workflow.nextInvocation}`)
  else parts.push([`wf ${workflow.slug}`, workflow.currentStage, workflow.selectedSlice].filter(Boolean).join(' · '))
  if (stageUsd !== null) parts.push(`$${stageUsd.toFixed(2)} stage`)
  if (hub !== null) parts.push(hubShortTextOf(hub))
  return parts.join(' · ')
}

/** `hub 9.157.0` or `hub down`, for the rows that have no room for the notice. */
export function hubShortTextOf(hub: HubHealth): string {
  return hub.ok ? `hub ${hub.version ?? '?'}` : 'hub down'
}

/** The workflows the strip rotates through: the active ones by slug, in a ring. */
export function nextActiveSlug(workflows: readonly WorkflowEntry[], current: string | null): string | null {
  const ring = [...ringSlugs(workflows, false), ...ringSlugs(workflows, true)]
  if (ring.length === 0) return null
  const at = current === null ? -1 : ring.indexOf(current)
  return ring[(at + 1) % ring.length] ?? null
}

function ringSlugs(workflows: readonly WorkflowEntry[], terminal: boolean): string[] {
  return workflows.filter(w => w.terminal === terminal).map(w => w.slug).sort()
}

/**
 * The workflows the strip may open on: the active ones, or every one when
 * none is active. The caller picks the newest by its index's mtime.
 */
export function openingCandidatesOf(workflows: readonly WorkflowEntry[]): WorkflowEntry[] {
  const active = workflows.filter(w => !w.terminal)
  return active.length > 0 ? active : [...workflows]
}

/** Rows a text takes when wrapped into `columns` cells (one at least). */
export function wrappedRowsOf(text: string, columns: number): number {
  const width = Math.max(1, columns)
  return Math.max(1, Math.ceil(text.length / width))
}

/** The footer mode label for a workflow, or null for a closed one. */
export function modeLabelOf(workflow: WorkflowEntry): string | null {
  if (workflow.terminal || !workflow.currentStage) return null
  return `wf:${workflow.currentStage}`
}

/** The spinner's word while a `/wf <key>` turn runs, or null to keep the engine's. */
export function spinnerWordOf(command: WfCommand): string | null {
  const verbs: Record<string, string> = {
    shape: 'Shaping',
    slice: 'Slicing',
    plan: 'Planning',
    implement: 'Implementing',
    verify: 'Verifying',
    review: 'Reviewing',
    handoff: 'Handing off',
    ship: 'Shipping',
    retro: 'Reflecting',
    design: 'Designing',
    probe: 'Probing',
    simplify: 'Simplifying',
    auto: 'Driving',
    yolo: 'Driving',
    campaign: 'Campaigning',
    task: 'Working',
    status: 'Inspecting',
    recap: 'Recapping',
    close: 'Closing',
    docs: 'Documenting',
    observability: 'Instrumenting',
  }
  const verb = verbs[command.key]
  if (verb === undefined) return null
  // Reviews mode is no slice: it fixes the review findings of the workflow's slices.
  if (command.key === 'implement' && command.slice === 'reviews') return command.slug === null ? 'Fixing review findings' : `Fixing review findings in ${command.slug}`
  const target = command.slice ?? command.slug
  return target === null ? verb : `${verb} ${target}`
}

/**
 * The tokens a `cost.jsonl` ledger sums to, main and subagent rows alike: the
 * new input, the cache writes and the output. A cache read is the same context
 * read again on every call, so it is not counted: with it, a long workflow
 * reads as billions of tokens.
 */
export function ledgerTokensOf(text: string): number {
  let total = 0
  for (const line of text.split(/\r?\n/u)) {
    if (line.trim() === '') continue
    let row: unknown
    try {
      row = JSON.parse(line)
    } catch {
      continue
    }
    if (!row || typeof row !== 'object') continue
    const record = row as { main?: unknown; subagents?: unknown }
    total += tokensOf(record.main)
    if (Array.isArray(record.subagents)) for (const sub of record.subagents) total += tokensOf(sub)
  }
  return total
}

function tokensOf(usage: unknown): number {
  if (!usage || typeof usage !== 'object') return 0
  const u = usage as Record<string, unknown>
  const int = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? Math.max(0, Math.floor(v)) : 0)
  // A Codex row (`lib/cost-ledger.mjs`): its input holds the cached input, and its output holds the reasoning.
  if (u['fields'] === 'codex' || 'cached_input_tokens' in u) {
    return Math.max(0, int(u['input_tokens']) - int(u['cached_input_tokens'])) + int(u['cache_write_input_tokens']) + int(u['output_tokens'])
  }
  return int(u['input_tokens']) + int(u['cache_creation_input_tokens']) + int(u['output_tokens'])
}

/** `1.2B`, `1.2M`, `340k`, `900` for a token count. */
export function tokensText(count: number): string {
  if (count >= 1_000_000_000) return `${(count / 1_000_000_000).toFixed(1)}B`
  if (count >= 1_000_000) return `${(count / 1_000_000).toFixed(1)}M`
  if (count >= 1_000) return `${Math.round(count / 1_000)}k`
  return String(count)
}

/** The strip's detail row: the last stage in dollars, the workflow in ledger tokens, and the hub. */
export function costTextOf(stageUsd: number | null, ledgerTokens: number | null): string | null {
  const parts: string[] = []
  if (stageUsd !== null) parts.push(`$${stageUsd.toFixed(2)} this stage`)
  if (ledgerTokens !== null) parts.push(`${tokensText(ledgerTokens)} tokens workflow`)
  return parts.length === 0 ? null : parts.join(' · ')
}

/** The strip's cost, short enough to pin right: the last stage in dollars, the workflow in tokens. */
export function costShortOf(stageUsd: number | null, ledgerTokens: number | null): string | null {
  const parts: string[] = []
  if (stageUsd !== null) parts.push(`$${stageUsd.toFixed(2)}`)
  if (ledgerTokens !== null) parts.push(`${tokensText(ledgerTokens)} tok`)
  return parts.length === 0 ? null : parts.join(' · ')
}

/** The hub health answer's fields the notice draws. */
export type HubHealth = { version: string | null; repos: number | null; stale: number | null; ok: boolean }

export function hubHealthOf(text: string): HubHealth {
  let body: unknown
  try {
    body = JSON.parse(text)
  } catch {
    return { version: null, repos: null, stale: null, ok: false }
  }
  if (!body || typeof body !== 'object') return { version: null, repos: null, stale: null, ok: false }
  const r = body as Record<string, unknown>
  const version = typeof r['version'] === 'string' ? r['version'] : null
  const entries = Array.isArray(r['entries']) ? (r['entries'] as Array<Record<string, unknown>>) : null
  const repos = entries === null ? null : entries.length
  const stale = entries === null ? null : entries.filter(entry => entry['stale'] === true).length
  return { version, repos, stale, ok: r['ok'] === true }
}

export function hubNoticeTextOf(health: HubHealth | null): string {
  if (health === null || !health.ok) return 'sdlc hub down'
  const parts = [`sdlc hub ${health.version ?? '?'}`]
  if (health.repos !== null) parts.push(`${health.repos} repos`)
  if (health.stale !== null && health.stale > 0) parts.push(`${health.stale} renders stale`)
  return parts.join(' · ')
}

/** The three-cell progress mark of a slice: plan, implement, verify. */
export function sliceMarkOf(slice: SliceEntry): string {
  const filled = slice.stage === 'verified' ? 3 : slice.stage === 'implemented' ? 2 : slice.stage === 'planned' ? 1 : 0
  return '▰'.repeat(filled) + '▱'.repeat(3 - filled)
}

/**
 * The items of a YAML list under a top-level key (`findings:`), each as its
 * scalar fields; null when the text has no such list. Enough YAML for the
 * ledgers: a list item starts with `- `, its fields are `key: value` lines
 * indented past the dash, and nested lists are skipped.
 */
export function yamlListItemsOf(text: string, key: string): Array<Record<string, string>> | null {
  const lines = text.split(/\r?\n/u)
  const start = lines.findIndex(line => line.replace(/\s+$/u, '') === `${key}:`)
  if (start === -1) return null
  const items: Array<Record<string, string>> = []
  let item: Record<string, string> | null = null
  /** The column of the items' dashes, from the first; a deeper dash is a nested list. */
  let itemIndent = -1
  /** The column of the items' fields, from the first; a deeper line is nested. */
  let fieldIndent = -1
  for (const line of lines.slice(start + 1)) {
    if (line.trim() === '') continue
    if (/^\S/u.test(line)) break
    const indent = line.length - line.trimStart().length
    const dash = /^\s*-\s*(.*)$/u.exec(line)
    if (dash !== null && (itemIndent === -1 || indent === itemIndent)) {
      itemIndent = indent
      item = {}
      items.push(item)
      const field = /^([\w-]+):\s*(.*)$/u.exec(dash[1] ?? '')
      if (field !== null) {
        fieldIndent = indent + 2
        item[field[1] as string] = unquoted(field[2] ?? '')
      }
      continue
    }
    if (dash !== null || item === null || indent <= itemIndent) continue
    if (fieldIndent === -1) fieldIndent = indent
    if (indent !== fieldIndent) continue
    const field = /^([\w-]+):\s*(.*)$/u.exec(line.trimStart())
    if (field !== null && !((field[1] as string) in item)) item[field[1] as string] = unquoted(field[2] ?? '')
  }
  return items
}

function unquoted(value: string): string {
  const trimmed = value.trim()
  const quoted = /^"(.*)"$|^'(.*)'$/u.exec(trimmed)
  return quoted ? (quoted[1] ?? quoted[2] ?? '').trim() : trimmed
}

/** The finding statuses a review ledger counts as open (review/_artifact.md Step 5b). */
const OPEN_FINDING_STATUSES: ReadonlySet<string> = new Set(['open', 'deferred', 'could-not-fix'])

/**
 * Open rows of a review ledger: the `findings:` items whose status is open
 * (absent counts as open), else, without such a list, unchecked markdown rows.
 */
export function openFindingsOf(text: string): number {
  const items = yamlListItemsOf(text, 'findings')
  if (items !== null) return items.filter(item => OPEN_FINDING_STATUSES.has((item['status'] ?? 'open').toLowerCase())).length
  return (text.match(/^\s*[-*]\s+\[ \]\s/gmu) ?? []).length
}

/** Open BLOCKER and HIGH findings of `.ai/ship-plan-audit.md`: the rows its triage gate counts. */
export function shipPlanBlockersOf(text: string): number {
  const items = yamlListItemsOf(text, 'findings') ?? []
  return items.filter(item => (item['status'] ?? 'open').toLowerCase() === 'open' && /^(?:BLOCKER|HIGH)$/iu.test(item['severity'] ?? '')).length
}

/**
 * The review ledger a workflow's dashboard row reads, from the names in its
 * directory: the sweep-level sibling YAML (`07-review.yaml`, else the selected
 * slice's), else the last YAML by name; the markdown by the same rule when
 * there is no YAML.
 */
export function reviewLedgerNameOf(names: readonly string[], selectedSlice: string | null): string | null {
  const ledgers = names.filter(name => /^07-review.*\.(?:md|yaml)$/u.test(name)).sort()
  for (const extension of ['yaml', 'md']) {
    const own = ledgers.filter(name => name.endsWith(`.${extension}`))
    if (own.length === 0) continue
    const sweep =
      own.find(name => name === `07-review.${extension}`) ??
      (selectedSlice === null ? undefined : own.find(name => name === `07-review-${selectedSlice}.${extension}`))
    return sweep ?? (own[own.length - 1] as string)
  }
  return null
}

