/**
 * The picker's state machine, pure: which step a command opens at, the
 * options each step offers, and what a pick does (the next step, or the
 * command text to fill into the prompt).
 */
import { CATALOG, entryOf } from './catalog.ts'
import type { ArgumentNeed } from './catalog.ts'
import type { SliceEntry, WorkflowEntry } from './workflows.ts'

export type Step =
  | { kind: 'key' }
  | { kind: 'slug'; key: string }
  | { kind: 'slice'; key: string; slug: string }

export type Option = { value: string; label: string }

export type Outcome =
  | { kind: 'step'; step: Step }
  | { kind: 'fill'; text: string }

/** The value of the option that ends a step without a slug or a slice. */
export const NONE = '-'
/** The value of the `all` option `plan` offers for its slice. */
export const ALL = 'all'

/**
 * Which step a run of `/wf <key> <args>` opens at, or null when the typed
 * arguments already satisfy the key and the command should run as typed.
 *
 * A bare `/wf` opens at the key step. A key with no argument that needs a
 * slug opens at the slug step. A key whose arguments already hold a slug runs
 * as typed: its slice is optional, and a person who typed or sent the slug
 * (from the phone, where the band does not draw) is not held for one. The
 * slice step opens only from the picker's own slug step (`pick`).
 */
export function stepFor(key: string | null, args: string): Step | null {
  const tokens = args.trim() === '' ? [] : args.trim().split(/\s+/u)
  if (key === null) {
    if (tokens.length === 0) return { kind: 'key' }
    const typed = tokens[0] as string
    const entry = entryOf(typed)
    if (entry === null) return null
    // A typed `/wf status` is complete: a key whose slug is optional runs without one.
    if (tokens.length === 1 && entry.need === 'slug-optional') return null
    return stepFor(typed, tokens.slice(1).join(' '))
  }
  const entry = entryOf(key)
  if (entry === null) return null
  if (tokens.length === 0) {
    return entry.need === 'none' ? null : { kind: 'slug', key }
  }
  return null
}

/** How many open workflows the opened text names before it says "and N more". */
const NAMED_WORKFLOWS = 6

/**
 * What a command that opened the picker answers: where the list is, and the
 * whole command to send instead, for a person whose client draws no band (the
 * phone over Remote Control). A step that asks for a workflow names the open ones.
 */
export function openedTextOf(step: Step, workflows: readonly WorkflowEntry[]): string {
  const head = 'Pick from the list above the prompt'
  if (step.kind === 'key') return `${head}, or send /wf <key> <slug>.`
  const key = step.kind === 'slug' ? step.key : `${step.key} ${step.slug}`
  const form = step.kind === 'slug' ? `/wf ${key} <slug>` : `/wf ${key} <slice>`
  if (step.kind !== 'slug') return `${head}, or send ${form}.`
  const open = workflows.filter(workflow => !workflow.terminal).map(workflow => workflow.slug)
  if (open.length === 0) return `${head}, or send ${form}.`
  const named = open.slice(0, NAMED_WORKFLOWS).join(', ')
  const more = open.length > NAMED_WORKFLOWS ? ` and ${open.length - NAMED_WORKFLOWS} more` : ''
  return `${head}, or send ${form}. Open workflows: ${named}${more}.`
}

export function takesSlice(need: ArgumentNeed): boolean {
  return need === 'slug-slice-optional' || need === 'slug-slice-or-all'
}

/** The heading the band draws for a step. */
export function titleOf(step: Step): string {
  if (step.kind === 'key') return '/wf — pick a key'
  if (step.kind === 'slug') return `/wf ${step.key} — pick a workflow`
  return `/wf ${step.key} ${step.slug} — pick a slice`
}

/** The options of the key step: every key with its description. */
export function keyOptions(): Option[] {
  return CATALOG.map(entry => ({ value: entry.key, label: `${entry.key}  ${entry.description}` }))
}

/**
 * The options of the slug step: active workflows first, then closed ones,
 * each with its status, stage, and selected slice. An optional-slug key
 * offers "no slug" first.
 */
export function slugOptions(step: Extract<Step, { kind: 'slug' }>, workflows: readonly WorkflowEntry[]): Option[] {
  const entry = entryOf(step.key)
  const options: Option[] = []
  if (entry?.need === 'slug-optional') options.push({ value: NONE, label: '(no slug)' })
  const ordered = [...workflows.filter(w => !w.terminal), ...workflows.filter(w => w.terminal)]
  for (const workflow of ordered) options.push({ value: workflow.slug, label: workflowLabel(workflow) })
  return options
}

export function workflowLabel(workflow: WorkflowEntry): string {
  const parts = [workflow.terminal ? `closed (${workflow.status})` : workflow.status]
  if (!workflow.terminal && workflow.currentStage) parts.push(`stage ${workflow.currentStage}`)
  if (!workflow.terminal && workflow.selectedSlice) parts.push(`slice ${workflow.selectedSlice}`)
  return `${workflow.slug}  ${parts.join(' · ')}`
}

/**
 * The options of the slice step: "no slice" first, `all` for `plan`, then
 * every slice with its roster status and the furthest stage file present.
 */
export function sliceOptions(step: Extract<Step, { kind: 'slice' }>, slices: readonly SliceEntry[]): Option[] {
  const entry = entryOf(step.key)
  const options: Option[] = [{ value: NONE, label: '(no slice)' }]
  if (entry?.need === 'slug-slice-or-all') options.push({ value: ALL, label: 'all  every slice' })
  for (const slice of slices) options.push({ value: slice.slug, label: sliceLabel(slice) })
  return options
}

export function sliceLabel(slice: SliceEntry): string {
  const parts = [slice.status]
  if (slice.stage !== 'defined') parts.push(slice.stage)
  if (slice.complexity) parts.push(slice.complexity)
  return `${slice.slug}  ${parts.join(' · ')}`
}

/**
 * What a pick does. `hasSlices` says whether the picked workflow carries a
 * roster, so a key that may take a slice skips the slice step without one.
 */
export function pick(step: Step, value: string, hasSlices: (slug: string) => boolean): Outcome {
  if (step.kind === 'key') {
    const entry = entryOf(value)
    if (entry === null || entry.need === 'none') return { kind: 'fill', text: fillOf(value) }
    return { kind: 'step', step: { kind: 'slug', key: value } }
  }
  if (step.kind === 'slug') {
    if (value === NONE) return { kind: 'fill', text: fillOf(step.key) }
    const entry = entryOf(step.key)
    if (entry !== null && takesSlice(entry.need) && hasSlices(value)) {
      return { kind: 'step', step: { kind: 'slice', key: step.key, slug: value } }
    }
    return { kind: 'fill', text: fillOf(step.key, value) }
  }
  if (value === NONE) return { kind: 'fill', text: fillOf(step.key, step.slug) }
  return { kind: 'fill', text: fillOf(step.key, step.slug, value) }
}

/** The command text the prompt receives, with a trailing space for more arguments. */
export function fillOf(key: string, slug?: string, slice?: string): string {
  return `/wf ${[key, slug, slice].filter(part => part !== undefined && part !== '').join(' ')} `
}

/** One page of options: at most `size` rows, `size` never below one. */
export type Page = { items: Option[]; page: number; pages: number }

/**
 * The options a page shows, so every row can carry a one-digit hotkey. The
 * page index wraps, so a "more" press after the last page shows the first.
 */
export function pageOf(options: readonly Option[], page: number, size: number): Page {
  const width = Math.max(1, Math.floor(size))
  const pages = Math.max(1, Math.ceil(options.length / width))
  const index = ((page % pages) + pages) % pages
  return { items: options.slice(index * width, index * width + width), page: index, pages }
}

/** The most rows one page may hold: the nine digits; `0` turns the page. */
export const MAX_PAGE_SIZE = 9

/** The hotkey of the row at `index` on its page: `1`–`9`; none past nine. */
export function hotkeyOf(index: number): string | undefined {
  if (index < 0 || index >= MAX_PAGE_SIZE) return undefined
  return String(index + 1)
}

/** The step a "back" press returns to: the key step from a slug step, the slug step from a slice step; none from the key step. */
export function backOf(step: Step): Step | null {
  if (step.kind === 'slug') return { kind: 'key' }
  if (step.kind === 'slice') return { kind: 'slug', key: step.key }
  return null
}

/**
 * What a digit typed into the filter field means: `1`–`9` the row at that
 * position on the page shown, `0` the next page. Any other text is a filter.
 */
export type DigitCommand = { kind: 'row'; index: number } | { kind: 'more' }

export function digitCommandOf(text: string): DigitCommand | null {
  const trimmed = text.trim()
  if (!/^[0-9]$/u.test(trimmed)) return null
  return trimmed === '0' ? { kind: 'more' } : { kind: 'row', index: Number(trimmed) - 1 }
}

/** The filter the rows narrow by: a bare digit is a pick, not a filter. */
export function filterTextOf(text: string): string {
  return digitCommandOf(text) === null ? text : ''
}

/**
 * What Enter in the filter field does: a digit picks that row of the page
 * shown (`0` turns the page); other text picks the first row it leaves;
 * nothing when no row fits.
 */
export type SubmitAction = { kind: 'pick'; value: string } | { kind: 'more' }

export function submitActionOf(text: string, page: Page, options: readonly Option[]): SubmitAction | null {
  const digit = digitCommandOf(text)
  if (digit !== null) {
    if (digit.kind === 'more') return { kind: 'more' }
    const row = page.items[digit.index]
    return row === undefined ? null : { kind: 'pick', value: row.value }
  }
  const first = filterOptions(options, text)[0]
  return first === undefined ? null : { kind: 'pick', value: first.value }
}

/** The options whose value or label holds every word of `text`, case-insensitively. */
export function filterOptions(options: readonly Option[], text: string): Option[] {
  const words = text.trim().toLowerCase().split(/\s+/u).filter(Boolean)
  if (words.length === 0) return [...options]
  return options.filter(option => {
    const haystack = `${option.value} ${option.label}`.toLowerCase()
    return words.every(word => haystack.includes(word))
  })
}

/**
 * What a command does after its fill: `filled`, the prompt box holds it for the
 * person's Enter; `submit`, the surface draws its own prompt box (the Desktop
 * app answers every fill `no_composer`), so the command goes in as the person's
 * prompt; `type`, the box is busy or the cause is unknown, so the person types it.
 */
export function afterFillOf(isFilled: boolean, refusal: string | undefined): 'filled' | 'submit' | 'type' {
  if (isFilled) return 'filled'
  return refusal === 'no_composer' ? 'submit' : 'type'
}

/** `/wf`, `/sdlc-workflow:wf`, or a `/wf-<word>` shortcut at the start of a draft. */
const DRAFT_HEAD = /^\/(?:sdlc-workflow:)?wf(?:-([a-z][a-z-]*))?(?=\s|$)/u

/**
 * The picker step a draft in the prompt box asks for, and the filter the word
 * being typed sets; null when the draft is no `/wf` command, or is complete.
 *
 * `/wf` and `/wf pl` give the key step (filter `pl`); `/wf plan ` the
 * workflow step; `/wf plan al` the workflow step (filter `al`); `/wf plan
 * alpha ` the slice step where the key takes a slice. A `/wf-plan` shortcut
 * reads as `/wf plan`. A word that is no key, a key that needs nothing, or a
 * key past its last argument gives null.
 */
export function draftStepOf(draft: string): { step: Step; filter: string } | null {
  const text = draft.replace(/^\s+/u, '')
  const head = DRAFT_HEAD.exec(text)
  if (head === null) return null
  const rest = text.slice(head[0].length)
  const words = rest.trim() === '' ? [] : rest.trim().split(/\s+/u)
  const tokens = head[1] === undefined ? words : [head[1], ...words]
  // The last word is still being typed unless the draft ends in a space.
  const isTyping = tokens.length > 0 && !/\s$/u.test(text)
  const done = isTyping ? tokens.slice(0, -1) : tokens
  const filter = isTyping ? (tokens[tokens.length - 1] as string) : ''
  if (done.length === 0) {
    if (filter !== '' && !keyOptions().some(option => option.value.startsWith(filter))) return null
    return { step: { kind: 'key' }, filter }
  }
  const key = done[0] as string
  const entry = entryOf(key)
  if (entry === null || entry.need === 'none') return null
  if (done.length === 1) return { step: { kind: 'slug', key }, filter }
  if (done.length === 2 && takesSlice(entry.need)) return { step: { kind: 'slice', key, slug: done[1] as string }, filter }
  return null
}

/** True when two steps ask for the same pick. */
export function isSameStep(left: Step | null, right: Step | null): boolean {
  if (left === null || right === null) return left === right
  if (left.kind !== right.kind) return false
  if (left.kind === 'key') return true
  if (left.kind === 'slug') return right.kind === 'slug' && left.key === right.key
  return right.kind === 'slice' && left.key === right.key && left.slug === right.slug
}

